    if (f.off !== t.off || f.end !== t.end || f.kid !== t.kid || f.pd !== t.pd || f.fd !== t.fd || f.flags !== t.flags || f.td !== t.td) return false;
    if (am_text(text, f) !== am_text(text, t)) return false;
